// Safeguard marker: INSTAOPS_V2_SCHEDULE — atomically claims due SCHEDULED + LATER rows (Reels/Images/Carousels) from Supabase instaops_posts via instaops_claim_due_scheduled_posts and hands off canonical lock to W02.
return (async function () {
  var self = this;
  function readCfg(key, fallback) {
    var blocked = false;
    try {
      if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') {
        return { value: String($env[key]), source: 'env', blocked: false };
      }
    } catch (_) { blocked = true; }
    try {
      if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') {
        return { value: String($vars[key]), source: 'vars', blocked: blocked };
      }
    } catch (_) {}
    return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
  }

  async function httpCall(opts) {
    if (self && self.helpers && typeof self.helpers.httpRequest === 'function') {
      return await self.helpers.httpRequest(opts);
    }
    if (typeof fetch === 'function') {
      var headers = Object.assign({}, opts.headers || {});
      var body;
      if (opts.body !== undefined) {
        headers['Content-Type'] = headers['Content-Type'] || 'application/json';
        body = typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body);
      }
      var res = await fetch(opts.url, { method: opts.method || 'GET', headers: headers, body: body });
      var text = await res.text();
      var parsed = text;
      try { parsed = text ? JSON.parse(text) : {}; } catch (_) {}
      return { statusCode: res.status, body: parsed, headers: {} };
    }
    throw new Error('No HTTP helper available.');
  }

  var schedCfg = readCfg('SCHEDULING_ENABLED', 'false');
  var livePubCfg = readCfg('LIVE_PUBLISH_ENABLED', 'false');
  if (schedCfg.value.toLowerCase() !== 'true' || livePubCfg.value.toLowerCase() !== 'true') {
    return [];
  }

  var sbUrlCfg = readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co');
  var sbKeyCfg = readCfg('SUPABASE_SERVICE_ROLE_KEY', '');
  var n8nUrlCfg = readCfg('N8N_BASE_URL', 'https://137.23.61.127.sslip.io');
  var secretCfg = readCfg('N8N_WEBHOOK_SECRET', '');
  if (!sbKeyCfg.value || !secretCfg.value) {
    return [{ json: { ok: false, error: (sbKeyCfg.blocked || secretCfg.blocked) ? 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.' : 'Missing SUPABASE_SERVICE_ROLE_KEY or N8N_WEBHOOK_SECRET.' } }];
  }

  var sbUrl = sbUrlCfg.value.replace(/\/$/, '');
  var sbHeaders = { apikey: sbKeyCfg.value, Authorization: 'Bearer ' + sbKeyCfg.value, 'Content-Type': 'application/json' };
  var workerId = 'w03:' + String((typeof $execution !== 'undefined' && $execution && $execution.id) || Date.now());

  // Atomic FOR UPDATE SKIP LOCKED claim on SCHEDULED + LATER + due publish_at + approved_revision=revision
  var claimRes = await httpCall({
    method: 'POST',
    url: sbUrl + '/rest/v1/rpc/instaops_claim_due_scheduled_posts',
    headers: sbHeaders,
    body: { p_worker_id: workerId, p_limit: 1 },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 20000
  });

  var claimed = Array.isArray(claimRes.body) ? claimRes.body : [];
  if (claimRes.statusCode >= 300 || !claimed.length) {
    return [];
  }

  var row = claimed[0];
  var mediaType = String(row.media_type || 'REEL').toUpperCase();
  var activeAssets = Array.isArray(row.media_items) ? row.media_items : [];
  if ((mediaType === 'CAROUSEL' && (activeAssets.length < 2 || activeAssets.length > 10)) || Number(row.approved_revision) !== Number(row.revision)) {
    await httpCall({ method: 'POST', url: sbUrl + '/rest/v1/rpc/instaops_release_lock', headers: sbHeaders, body: { p_lock_key: row.lock_key, p_owner_id: row.lock_owner }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.post_uuid), headers: sbHeaders, body: { status: 'FAILED', error_code: 'SCHEDULE_PRECHECK_FAILED', error: 'Invalid carousel assets or revision mismatch on scheduled claim' }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return [];
  }

  var payload = {
    action: 'PUBLISH',
    post_uuid: String(row.post_uuid),
    post_id: String(row.post_id),
    ig_user_id: String(row.ig_user_id || readCfg('INSTAGRAM_USER_ID', '17841453414532595').value),
    media_type: mediaType,
    caption: String(row.caption || ''),
    media_url: String(row.media_url || ''),
    reviewed_revision: String(row.revision),
    approved_revision: String(row.approved_revision),
    confirm: true,
    lock_key: String(row.lock_key),
    lock_owner: String(row.lock_owner),
    job_id: String(row.job_id),
    request_id: String(row.request_id)
  };

  try {
    var dispRes = await httpCall({
      method: 'POST',
      url: n8nUrlCfg.value.replace(/\/$/, '') + '/webhook/instaops-publish-v1',
      headers: { 'x-dashboard-secret': secretCfg.value, 'Content-Type': 'application/json' },
      body: payload,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 30000
    });
    if (dispRes.statusCode >= 200 && dispRes.statusCode < 300 && dispRes.body && dispRes.body.accepted === true) {
      return [{ json: { ok: true, dispatched: true, post_uuid: row.post_uuid, post_id: row.post_id, lock_key: row.lock_key, job_id: row.job_id, execution_id: dispRes.body.execution_id } }];
    }
    if (dispRes.statusCode >= 400 && dispRes.statusCode < 500) {
      await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.post_uuid), headers: sbHeaders, body: { status: 'READY', error_code: 'SCHEDULE_DISPATCH_REJECTED', error: JSON.stringify(dispRes.body || {}).slice(0, 300) }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
      await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_jobs?job_id=eq.' + encodeURIComponent(row.job_id), headers: sbHeaders, body: { status: 'FAILED', stage: 'DISPATCH_REJECTED', finished_at: new Date().toISOString() }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
      await httpCall({ method: 'POST', url: sbUrl + '/rest/v1/rpc/instaops_release_lock', headers: sbHeaders, body: { p_lock_key: row.lock_key, p_owner_id: row.lock_owner }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
      return [{ json: { ok: false, dispatched: false, status: 'REJECTED', httpStatus: dispRes.statusCode } }];
    }
    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.post_uuid), headers: sbHeaders, body: { status: 'VERIFY_MANUALLY', error_code: 'PUBLISH_OUTCOME_UNKNOWN', error: 'Uncertain scheduled W02 webhook dispatch HTTP ' + dispRes.statusCode }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_jobs?job_id=eq.' + encodeURIComponent(row.job_id), headers: sbHeaders, body: { status: 'OUTCOME_UNKNOWN', stage: 'OUTCOME_UNKNOWN' }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return [{ json: { ok: false, dispatched: false, status: 'VERIFY_MANUALLY', lock_preserved: true } }];
  } catch (netErr) {
    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.post_uuid), headers: sbHeaders, body: { status: 'VERIFY_MANUALLY', error_code: 'PUBLISH_OUTCOME_UNKNOWN', error: 'Uncertain scheduled W02 dispatch timeout: ' + (netErr && netErr.message ? netErr.message : '') }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_jobs?job_id=eq.' + encodeURIComponent(row.job_id), headers: sbHeaders, body: { status: 'OUTCOME_UNKNOWN', stage: 'OUTCOME_UNKNOWN' }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return [{ json: { ok: false, dispatched: false, status: 'VERIFY_MANUALLY', lock_preserved: true } }];
  }
}).call(this);
